  <body>
    <div class="sidebar">

      ${photoPath ? `<img src="${photoPath}" class="photo" />` : ""}

      <h2>${data.name || ""}</h2>
      <p>${data.email || ""}</p>
      <p>${data.phone || ""}</p>
      <p>${data.linkedin || ""}</p>

      <h3>Skills</h3>
      <ul>
        ${(data.skills || []).map(s => `<li>${s}</li>`).join("")}
      </ul>
    </div>

    <div class="main">
      <h2>Professional Summary</h2>
      <p>${data.summary || ""}</p>

      <h2>Experience</h2>
      <ul>
        ${(data.experience || []).map(e => `<li>${e}</li>`).join("")}
      </ul>

      <h2>ATS Keywords</h2>
      <p>${(data.keywords || []).join(", ")}</p>
    </div>
  </body>
  </html>
  `;
}

// ================= TEMPLATE: SIMPLE =================
function templateSimple(data, photoPath) {
  return `
  <html>
  <body style="font-family: Arial; padding: 30px;">

    ${photoPath ? `<img src="${photoPath}" style="width:100px;border-radius:50%;margin-bottom:10px;" />` : ""}

    <h1>${data.name || ""}</h1>
    <p>${data.email || ""} | ${data.phone || ""} | ${data.linkedin || ""}</p>

    <h2>Summary</h2>
    <p>${data.summary || ""}</p>

    <h2>Skills</h2>
    <ul>
      ${(data.skills || []).map(s => `<li>${s}</li>`).join("")}
    </ul>

    <h2>Experience</h2>
    <ul>
      ${(data.experience || []).map(e => `<li>${e}</li>`).join("")}
    </ul>

    <h2>Keywords</h2>
    <p>${(data.keywords || []).join(", ")}</p>

  </body>
  </html>
  `;
}

// ================= TEMPLATE SWITCH =================
function generateHTML(data, template, photoPath) {
  if (template === "simple") return templateSimple(data, photoPath);
  return templateModern(data, photoPath);
}

// ================= MAIN FUNCTION =================
async function generatePDF(data, template = "modern") {
  let photoPath = "";

  // 🔥 FIX: convert local path → usable by Puppeteer
  if (data.photo) {
    photoPath = "file:///" + path.resolve(data.photo);
  }

  const html = generateHTML(data, template, photoPath);

  const browser = await puppeteer.launch();
  const page = await browser.newPage();

  await page.setContent(html, { waitUntil: "load" });

  const pdf = await page.pdf({
    format: "A4",
    printBackground: true,
  });

  await browser.close();

  return pdf;
}

module.exports = { generatePDF };
